import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  total: 0,
  itemCount: 0,
  lastUpdated: null,
};

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem: (state, action) => {
      const { product, quantity = 1 } = action.payload;
      const existingItem = state.items.find(item => item.id === product.id);

      if (existingItem) {
        existingItem.quantity += quantity;
      } else {
        state.items.push({ ...product, quantity });
      }

      state.itemCount += quantity;
      state.total += product.price * quantity;
      state.lastUpdated = new Date().toISOString();
    },

    removeItem: (state, action) => {
      const itemId = action.payload;
      const itemToRemove = state.items.find(item => item.id === itemId);

      if (itemToRemove) {
        state.itemCount -= itemToRemove.quantity;
        state.total -= itemToRemove.price * itemToRemove.quantity;
        state.items = state.items.filter(item => item.id !== itemId);
        state.lastUpdated = new Date().toISOString();
      }
    },

    updateQuantity: (state, action) => {
      const { itemId, quantity } = action.payload;
      const item = state.items.find(item => item.id === itemId);

      if (item && quantity > 0) {
        const diff = quantity - item.quantity;
        state.itemCount += diff;
        state.total += item.price * diff;
        item.quantity = quantity;
        state.lastUpdated = new Date().toISOString();
      }
    },

    clearCart: (state) => {
      state.items = [];
      state.total = 0;
      state.itemCount = 0;
      state.lastUpdated = new Date().toISOString();
    },

    setCart: (state, action) => {
      state.items = action.payload.items || [];
      state.total = action.payload.total || 0;
      state.itemCount = action.payload.itemCount || 0;
      state.lastUpdated = action.payload.lastUpdated || new Date().toISOString();
    }
  }
});

